export async function adjust(sku: string, delta: number) {
  return db.tx(async t => {
    const { qty } = await t.one('SELECT qty FROM stock WHERE sku=$1', [sku])
    await t.none('UPDATE stock SET qty=$1 WHERE sku=$2', [qty + delta, sku])
  })
})

